// RemoveEmf relationship.
// Sets o.R.Emf to nil.
// Removes o from all passed in related items' relationships struct.
func (o *Checklist) RemoveEmf(ctx context.Context, exec boil.ContextExecutor, related *EmpresaFilial) error {
	var err error

	queries.SetScanner(&o.EmfID, nil)
	if _, err = o.Update(ctx, exec, boil.Whitelist("emf_id")); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	if o.R != nil {
		o.R.Emf = nil
	}
	if related == nil || related.R == nil {
		return nil
	}

	for i, ri := range related.R.EmfChecklists {
		if queries.Equal(o.EmfID, ri.EmfID) {
			continue
		}

		ln := len(related.R.EmfChecklists)
		if ln > 1 && i < ln-1 {
			related.R.EmfChecklists[i] = related.R.EmfChecklists[ln-1]
		}
		related.R.EmfChecklists = related.R.EmfChecklists[:ln-1]
		break
	}
	return nil
}

