func ChecklistExists(ctx context.Context, exec boil.ContextExecutor, cKLID int) (bool, error) {
	var exists bool
	sql := "select exists(select 1 from `checklist` where `ckl_id`=? limit 1)"

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, sql)
		fmt.Fprintln(writer, cKLID)
	}
	row := exec.QueryRowContext(ctx, sql, cKLID)

	err := row.Scan(&exists)
	if err != nil {
		return false, errors.Wrap(err, "models: unable to check if checklist exists")
	}

	return exists, nil
}

// Exists checks if the Checklist row exists.
func (o *Checklist) Exists(ctx context.Context, exec boil.ContextExecutor) (bool, error) {
	return ChecklistExists(ctx, exec, o.CKLID)
}
